DECLARE q finance_document_requests%ROWTYPE; o finance_document_observations%ROWTYPE; d finance_document_registry%ROWTYPE;
 p jsonb; expected_payload jsonb; expected_result jsonb; ident jsonb; row_source record; x jsonb; previous finance_document_observations%ROWTYPE;
BEGIN
 SELECT * INTO q FROM finance_document_requests WHERE request_id=p_request;
 SELECT * INTO o FROM finance_document_observations WHERE request_id=p_request;
 IF q.request_id IS NULL OR o.observation_id IS NULL THEN RAISE EXCEPTION 'Orphan document registration' USING ERRCODE='23514';END IF;
 SELECT * INTO d FROM finance_document_registry WHERE document_id=o.document_id;ident:=o.preview_json->'identity';
 IF o.preview_json->>'previewHash' IS DISTINCT FROM finance_document_hash(o.preview_json-'previewHash')
  OR o.preview_json->>'schemaVersion' IS DISTINCT FROM 'de1a-document-preview-v1'
  OR o.preview_json->>'canRegister' IS DISTINCT FROM 'true' OR o.preview_json->'issues' IS DISTINCT FROM '[]'::jsonb
  OR o.preview_json->>'subjectId' IS DISTINCT FROM o.subject_id OR o.preview_json->>'reviewRevisionId' IS DISTINCT FROM o.review_revision_id
  OR o.preview_json#>>'{source,kind}' IS DISTINCT FROM o.source_kind OR o.preview_json#>>'{source,id}' IS DISTINCT FROM o.source_id
  OR o.preview_json->>'documentId' IS DISTINCT FROM o.document_id OR (o.preview_json->>'version')::integer IS DISTINCT FROM o.version-1
  OR q.payload_hash IS DISTINCT FROM finance_document_hash(q.payload_json)
  OR o.preview_json#>>'{observation,snapshotHash}' IS DISTINCT FROM finance_document_hash(o.safe_snapshot_json)
 THEN RAISE EXCEPTION 'Document stored proof hash mismatch' USING ERRCODE='23514';END IF;
 IF o.version>1 THEN
  SELECT * INTO previous FROM finance_document_observations WHERE observation_id=o.previous_observation_id;
  IF previous.document_id IS DISTINCT FROM o.document_id OR previous.version IS DISTINCT FROM o.version-1
   THEN RAISE EXCEPTION 'Document observation chain mismatch' USING ERRCODE='23514';END IF;
 END IF;
 expected_payload:=jsonb_build_object('subjectId',o.subject_id,'reviewRevisionId',o.review_revision_id,'sourceKind',o.source_kind,'sourceId',o.source_id,
  'expectedPreviewHash',o.preview_json->>'previewHash','expectedVersion',o.version-1);
 expected_result:=jsonb_build_object('documentId',o.document_id,'portionId',o.preview_json->>'portionId','observationId',o.observation_id,'version',o.version,'replayed',false);
 IF q.actor_user_id<>o.actor_user_id OR q.payload_json IS DISTINCT FROM expected_payload OR q.result_json IS DISTINCT FROM expected_result
  OR d.document_id IS NULL OR d.subject_id<>o.subject_id OR d.namespace IS DISTINCT FROM ident->>'namespace' OR d.key_hash IS DISTINCT FROM ident->>'keyHash'
  OR d.base_key_hash IS DISTINCT FROM ident->>'baseKeyHash' OR d.descriptor_hash IS DISTINCT FROM ident->>'descriptorHash'
  OR d.descriptor_json IS DISTINCT FROM o.safe_snapshot_json->'descriptor'
  OR d.base_descriptor_json IS DISTINCT FROM NULLIF(o.safe_snapshot_json->'baseDescriptor','null'::jsonb)
  OR d.descriptor_hash IS DISTINCT FROM finance_document_hash(d.descriptor_json)
  OR d.base_key_hash IS DISTINCT FROM finance_document_hash(d.base_descriptor_json)
  OR (o.version=1 AND (d.created_request_id<>o.request_id OR d.actor_user_id<>o.actor_user_id))
 THEN RAISE EXCEPTION 'Document request/owner agreement failed' USING ERRCODE='23514';END IF;
 IF NOT EXISTS(SELECT 1 FROM finance_document_portions WHERE document_id=d.document_id AND portion_id=o.preview_json->>'portionId' AND locator='whole'
   AND request_id=d.created_request_id AND actor_user_id=d.actor_user_id)
  OR (d.namespace='mcm-card-approval-v1' AND NOT EXISTS(SELECT 1 FROM finance_document_reservations WHERE document_id=d.document_id AND base_key_hash=d.base_key_hash AND base_descriptor_json=d.base_descriptor_json AND request_id=d.created_request_id AND actor_user_id=d.actor_user_id))
  OR (d.namespace<>'mcm-card-approval-v1' AND EXISTS(SELECT 1 FROM finance_document_reservations WHERE document_id=d.document_id))
 THEN RAISE EXCEPTION 'Document whole/reservation agreement failed' USING ERRCODE='23514';END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(o.preview_json#>'{observation,sources}') LOOP
  IF NOT EXISTS(SELECT 1 FROM finance_document_sources WHERE document_id=d.document_id AND source_kind=x->>'kind' AND source_id=x->>'id')
   THEN RAISE EXCEPTION 'Document alias binding missing' USING ERRCODE='23514';END IF;
 END LOOP;
 IF o.apply_xid=pg_current_xact_id_if_assigned() THEN
  p:=finance_document_preview(o.subject_id,o.review_revision_id,o.source_kind,o.source_id);
  IF (p-ARRAY['version','previewHash']) IS DISTINCT FROM (o.preview_json-ARRAY['version','previewHash'])
   THEN RAISE EXCEPTION 'Document sources changed during registration' USING ERRCODE='23514';END IF;
 END IF;
END

DECLARE n text;
BEGIN
 -- Deliberate ASCII space/hyphen normalization. Unknown/masked identifiers do not receive a token.
 n:=pg_catalog.replace(pg_catalog.replace(p_number,' ',''),'-','');
 IF n IS NULL OR n !~ '^[0-9]{12,19}$' THEN RETURN NULL; END IF;
 RETURN finance_document_hash(pg_catalog.jsonb_build_array('de1a-card-number-ascii-v1',n));
END

DECLARE p jsonb; candidate jsonb; prev finance_document_observations%ROWTYPE;
BEGIN
 PERFORM finance_document_write_lock();
 PERFORM finance_assert_document_definitions(current_schema());
 IF TG_TABLE_NAME='finance_document_observations' THEN
  candidate:=finance_document_candidate(NEW.subject_id,NEW.review_revision_id,NEW.source_kind,NEW.source_id);
  p:=candidate-ARRAY['_safeSnapshot','_descriptor','_baseDescriptor'];
  SELECT * INTO prev FROM finance_document_observations WHERE document_id=NEW.document_id ORDER BY version DESC LIMIT 1;
  IF p->>'canRegister' IS DISTINCT FROM 'true' OR NEW.preview_json IS DISTINCT FROM p OR NEW.document_id IS DISTINCT FROM p->>'documentId'
   OR NEW.version<>COALESCE(prev.version,0)+1 OR NEW.previous_observation_id IS DISTINCT FROM prev.observation_id
   OR NEW.apply_xid IS DISTINCT FROM pg_current_xact_id() OR NEW.safe_snapshot_json IS DISTINCT FROM candidate->'_safeSnapshot'
  THEN RAISE EXCEPTION 'Document observation proof or version mismatch' USING ERRCODE='23514';END IF;
 END IF;
 RETURN NEW;
END

DECLARE d finance_document_registry%ROWTYPE; o finance_document_observations%ROWTYPE; last_row finance_document_observations%ROWTYPE;
 docs jsonb:='[]'; history jsonb:='[]'; result jsonb; doc_count integer:=0; observation_count integer; previous_version integer; portion text;
BEGIN
 PERFORM finance_assert_document_definitions(current_schema());
 IF finance_supply_id(to_jsonb(p_subject)) IS DISTINCT FROM true OR (p_document IS NOT NULL AND finance_supply_id(to_jsonb(p_document)) IS DISTINCT FROM true)
  THEN RAISE EXCEPTION 'Invalid document list selection' USING ERRCODE='22023';END IF;
 FOR d IN SELECT * FROM finance_document_registry WHERE subject_id=p_subject AND (p_document IS NULL OR document_id=p_document) ORDER BY created_at DESC,document_id DESC LIMIT 101 LOOP
  doc_count:=doc_count+1;IF doc_count>100 THEN EXIT;END IF;observation_count:=0;previous_version:=0;
  -- All history is validated before a capped projection is returned. Current source/subject changes do not invalidate an old registration.
  FOR o IN SELECT * FROM finance_document_observations WHERE document_id=d.document_id ORDER BY version LOOP
   PERFORM finance_document_assert_request(o.request_id);
   IF o.version<>previous_version+1 THEN RAISE EXCEPTION 'Document observation history has a gap' USING ERRCODE='55000';END IF;
   previous_version:=o.version;observation_count:=observation_count+1;last_row:=o;
  END LOOP;
  IF observation_count=0 THEN RAISE EXCEPTION 'Document history is missing' USING ERRCODE='55000';END IF;
  SELECT portion_id INTO portion FROM finance_document_portions WHERE document_id=d.document_id AND locator='whole';
  docs:=docs||jsonb_build_array(jsonb_build_object('documentId',d.document_id,'portionId',portion,'version',last_row.version,
   'latestObservation',finance_document_summary(last_row.preview_json->'observation'),'observationCount',observation_count));
  IF p_document IS NOT NULL THEN
   SELECT COALESCE(jsonb_agg(v ORDER BY version DESC),'[]') INTO history FROM(
    SELECT version,jsonb_build_object('observationId',observation_id,'version',version,'reviewRevisionId',review_revision_id,
     'createdAt',created_at,'summary',finance_document_summary(preview_json->'observation')) v
    FROM finance_document_observations WHERE document_id=d.document_id ORDER BY version DESC LIMIT 100) h;
  END IF;
 END LOOP;
 result:=jsonb_build_object('documents',docs,'hasMore',doc_count>100);
 IF p_document IS NOT NULL THEN result:=result||jsonb_build_object('history',history,'historyHasMore',COALESCE(observation_count,0)>100);END IF;
 RETURN result;
EXCEPTION WHEN invalid_parameter_value OR serialization_failure OR deadlock_detected THEN RAISE;
 WHEN OTHERS THEN RAISE EXCEPTION 'Document archive unavailable: %',SQLERRM USING ERRCODE='55000';
END

DECLARE p jsonb; candidate jsonb; payload jsonb; answer jsonb; old finance_document_requests%ROWTYPE; prev text; observation_id text; x jsonb;
BEGIN
 PERFORM finance_document_write_lock();PERFORM finance_assert_document_definitions(current_schema());
 IF finance_supply_id(to_jsonb(p_request)) IS DISTINCT FROM true OR finance_supply_id(to_jsonb(p_actor)) IS DISTINCT FROM true
  OR p_expected_version IS NULL OR p_expected_version<0 OR p_expected_hash IS NULL OR p_expected_hash !~ '^[a-f0-9]{64}$'
 THEN RAISE EXCEPTION 'Invalid document registration request' USING ERRCODE='22023';END IF;
 payload:=jsonb_build_object('subjectId',p_subject,'reviewRevisionId',p_review_revision,'sourceKind',p_kind,'sourceId',p_source,'expectedPreviewHash',p_expected_hash,'expectedVersion',p_expected_version);
 SELECT * INTO old FROM finance_document_requests WHERE request_id=p_request;
 IF FOUND THEN
  IF old.actor_user_id<>p_actor OR old.payload_json IS DISTINCT FROM payload OR old.payload_hash<>finance_document_hash(payload)
   THEN RAISE EXCEPTION 'Document request conflict' USING ERRCODE='23514';END IF;
  PERFORM finance_document_assert_request(p_request);
  RETURN old.result_json||jsonb_build_object('replayed',true);
 END IF;
 candidate:=finance_document_candidate(p_subject,p_review_revision,p_kind,p_source);p:=candidate-ARRAY['_safeSnapshot','_descriptor','_baseDescriptor'];
 IF p->>'canRegister' IS DISTINCT FROM 'true' OR p->>'previewHash'<>p_expected_hash OR (p->>'version')::integer<>p_expected_version
  THEN RAISE EXCEPTION 'Document preview changed or selection is unresolved' USING ERRCODE='23514';END IF;
 IF p_expected_version=0 THEN
  INSERT INTO finance_document_registry(document_id,subject_id,namespace,key_hash,base_key_hash,descriptor_hash,descriptor_json,base_descriptor_json,created_request_id,actor_user_id)
   VALUES(p->>'documentId',p_subject,p#>>'{identity,namespace}',p#>>'{identity,keyHash}',p#>>'{identity,baseKeyHash}',p#>>'{identity,descriptorHash}',candidate->'_descriptor',NULLIF(candidate->'_baseDescriptor','null'::jsonb),p_request,p_actor);
  INSERT INTO finance_document_portions(portion_id,document_id,locator,request_id,actor_user_id) VALUES(p->>'portionId',p->>'documentId','whole',p_request,p_actor);
  IF p#>>'{identity,baseKeyHash}' IS NOT NULL THEN
   INSERT INTO finance_document_reservations(namespace,base_key_hash,base_descriptor_json,document_id,request_id,actor_user_id)
    VALUES('mcm-card-approval-v1',p#>>'{identity,baseKeyHash}',candidate->'_baseDescriptor',p->>'documentId',p_request,p_actor);
  END IF;
 END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(p#>'{observation,sources}') LOOP
  IF NOT EXISTS(SELECT 1 FROM finance_document_sources WHERE source_kind=x->>'kind' AND source_id=x->>'id') THEN
   INSERT INTO finance_document_sources(source_kind,source_id,document_id,request_id,actor_user_id) VALUES(x->>'kind',x->>'id',p->>'documentId',p_request,p_actor);
  END IF;
 END LOOP;
 SELECT o.observation_id INTO prev FROM finance_document_observations o WHERE document_id=p->>'documentId' ORDER BY version DESC LIMIT 1;
 observation_id:='fdo-'||gen_random_uuid()::text;
 INSERT INTO finance_document_observations(observation_id,document_id,version,previous_observation_id,subject_id,review_revision_id,source_kind,source_id,preview_json,safe_snapshot_json,request_id,actor_user_id)
  VALUES(observation_id,p->>'documentId',p_expected_version+1,prev,p_subject,p_review_revision,p_kind,p_source,p,candidate->'_safeSnapshot',p_request,p_actor);
 answer:=jsonb_build_object('documentId',p->>'documentId','portionId',p->>'portionId','observationId',observation_id,'version',p_expected_version+1,'replayed',false);
 INSERT INTO finance_document_requests(request_id,actor_user_id,payload_json,payload_hash,result_json) VALUES(p_request,p_actor,payload,finance_document_hash(payload),answer);
 RETURN answer;
END

DECLARE req text; d finance_document_registry%ROWTYPE; o finance_document_observations%ROWTYPE;
BEGIN
 IF TG_TABLE_NAME='finance_document_registry' THEN req:=NEW.created_request_id;ELSE req:=NEW.request_id;END IF;
 PERFORM finance_document_assert_request(req);
 IF TG_TABLE_NAME IN('finance_document_sources','finance_document_reservations','finance_document_portions') THEN
  SELECT * INTO o FROM finance_document_observations WHERE request_id=req;
  IF NEW.document_id IS DISTINCT FROM o.document_id OR NEW.actor_user_id IS DISTINCT FROM o.actor_user_id THEN RAISE EXCEPTION 'Document subordinate owner mismatch' USING ERRCODE='23514';END IF;
  IF TG_TABLE_NAME='finance_document_sources' THEN
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(o.preview_json#>'{observation,sources}') s WHERE s->>'kind'=NEW.source_kind AND s->>'id'=NEW.source_id)
    THEN RAISE EXCEPTION 'Unexpected document alias binding' USING ERRCODE='23514';END IF;
  END IF;
 END IF;
 RETURN NULL;
END

DECLARE chosen jsonb; other jsonb; sid text;
BEGIN
 IF vat_followup_date(p_date) IS DISTINCT FROM true THEN RETURN NULL; END IF;
 SELECT payload_json INTO chosen FROM vat_filing_subject_revisions
 WHERE subject_id=p_subject AND payload_json->>'effectiveFrom'<=p_date
   AND (payload_json->>'effectiveTo' IS NULL OR payload_json->>'effectiveTo'>=p_date) ORDER BY version DESC LIMIT 1;
 IF chosen IS NULL OR chosen->>'state' IS DISTINCT FROM 'verified' OR chosen->>'entityType' IS DISTINCT FROM 'corporation'
  OR chosen->>'vatRegime' IS DISTINCT FROM 'general' OR chosen->>'filingUnit' IS DISTINCT FROM 'single_business_place'
  OR COALESCE(chosen->>'corpNum','') !~ '^[0-9]{10}$' THEN RETURN NULL; END IF;
 IF EXISTS(SELECT 1 FROM vat_filing_subject_revisions r WHERE r.subject_id=p_subject AND r.version>(chosen->>'version')::integer
   AND r.payload_json->>'effectiveFrom'<=p_date AND r.payload_json->>'effectiveTo'<p_date
   AND r.payload_json->>'effectiveFrom'<=COALESCE(chosen->>'effectiveTo','9999-12-31')
   AND chosen->>'effectiveFrom'<=r.payload_json->>'effectiveTo') THEN RETURN NULL; END IF;
 FOR sid IN SELECT DISTINCT subject_id FROM vat_filing_subject_revisions WHERE subject_id<>p_subject LOOP
  SELECT payload_json INTO other FROM vat_filing_subject_revisions
   WHERE subject_id=sid AND payload_json->>'effectiveFrom'<=p_date
    AND (payload_json->>'effectiveTo' IS NULL OR payload_json->>'effectiveTo'>=p_date) ORDER BY version DESC LIMIT 1;
  IF other IS NOT NULL AND other->>'corpNum'=chosen->>'corpNum' AND NOT EXISTS(
   SELECT 1 FROM vat_filing_subject_revisions r WHERE r.subject_id=sid AND r.version>(other->>'version')::integer
    AND r.payload_json->>'effectiveFrom'<=p_date AND r.payload_json->>'effectiveTo'<p_date
    AND r.payload_json->>'effectiveFrom'<=COALESCE(other->>'effectiveTo','9999-12-31')
    AND other->>'effectiveFrom'<=r.payload_json->>'effectiveTo') THEN RETURN NULL; END IF;
 END LOOP;
 RETURN chosen;
END

BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'Document writes require READ COMMITTED for fresh source snapshots after locks' USING ERRCODE='23514';
 END IF;
 PERFORM pg_advisory_xact_lock(1296256326,1);
 -- SHARE prevents source INSERT/UPDATE/DELETE while a registration is being validated, without installing old-table triggers.
 LOCK TABLE card_registry,card_transactions,hometax_tax_invoices,tax_invoices,vat_filing_subjects,vat_filing_subject_revisions,
  finance_supply_review_cases,finance_supply_review_revisions IN SHARE MODE;
END

