   AND r.payload_json->>''effectiveFrom''<=COALESCE(chosen->>''effectiveTo'',''9999-12-31'')
   AND chosen->>''effectiveFrom''<=r.payload_json->>''effectiveTo'') THEN RETURN NULL; END IF;
