  SELECT payload_json INTO other FROM vat_filing_subject_revisions
   WHERE subject_id=sid AND payload_json->>''effectiveFrom''<=p_date
    AND (payload_json->>''effectiveTo'' IS NULL OR payload_json->>''effectiveTo''>=p_date) ORDER BY version DESC LIMIT 1;
